(()=>{
const characters=[
 [1,'風之劍聖'],[2,'狂戰士'],[3,'神箭手'],[4,'封印師'],[5,'暗殺者'],[6,'聖女'],[7,'天使'],[8,'魔法少女'],[9,'魔劍士'],[10,'聖槍騎士'],[11,'元素師'],[12,'冒險家'],[13,'瘟疫法師'],[14,'仲裁者'],[15,'神官'],[16,'祈禱師'],[17,'賢者'],[18,'靈符師'],[19,'劍帝'],[20,'格鬥家'],[21,'勇者'],[22,'靈魂術士'],[23,'血之巫女'],[24,'蝶舞者'],[25,'女武神'],[26,'魔弓'],[27,'紅蓮騎士'],[28,'英靈人形'],[29,'魔槍'],[30,'蒼炎魔女'],[31,'吟游詩人'],[32,'精靈射手'],[33,'陰陽師'],[34,'血色劍靈'],[35,'月之女神'],[36,'獸靈武士'],[37,'聖弓'],[38,'紅衣主教'],[39,'記錄者'],[41,'聖庭檢察士'],[42,'星墜女巫'],[43,'戰鬥法師'],[44,'獵巫人'],[45,'聖殿騎士'],[46,'矜貴之女'],[48,'噬神者'],[49,'神秘學者'],[50,'女僕長'],[52,'結界師'],[53,'染污者'],[55,'傳教士'],[66,'異教徒']
].map(([id,name])=>({id,name,image:`assets/avatars/${String(id).padStart(2,'0')}.png`}));
const sequence=[
 {type:'re',team:'red',round:1,roundStart:true},{type:'re',team:'blue',round:1},
 {type:'ban',team:'blue',round:1},{type:'ban',team:'red',round:1},{type:'ban',team:'blue',round:1},
 {type:'insert',team:'blue',round:1},{type:'pick',team:'red',round:1},{type:'insert',team:'red',round:1},{type:'pick',team:'blue',round:1},
 {type:'re',team:'blue',round:2,roundStart:true},{type:'re',team:'red',round:2},
 {type:'ban',team:'red',round:2},{type:'ban',team:'blue',round:2},{type:'ban',team:'red',round:2},
 {type:'insert',team:'red',round:2},{type:'pick',team:'blue',round:2},{type:'insert',team:'blue',round:2},{type:'pick',team:'red',round:2},
 {type:'re',team:'blue',round:3,roundStart:true},{type:'re',team:'red',round:3},
 {type:'ban',team:'red',round:3},{type:'ban',team:'blue',round:3},{type:'ban',team:'red',round:3},
 {type:'insert',team:'red',round:3},{type:'pick',team:'blue',round:3},{type:'insert',team:'blue',round:3},{type:'pick',team:'red',round:3}
];
const pickOrder=[['red',0],['blue',0],['blue',1],['red',1],['blue',2],['red',2]];
const tableOrder=[['red',0],['blue',0],['blue',1],['red',1],['blue',2],['red',2]];
const SPRITE_DATA='data:image/webp;base64,';
const spriteIndex=new Map(characters.map((character,index)=>[character.id,index]));
document.documentElement.style.setProperty('--avatar-sprite',`url("${SPRITE_DATA}")`);
function avatarHtml(id,extra='avatar'){const index=spriteIndex.get(Number(id)),x=(index%8)*100/7,y=Math.floor(index/8)*100/6;return`<span class="${extra} avatar sprite-avatar" style="background-position:${x}% ${y}%" role="img" aria-label="${role(id).name}"></span>`}
const q=id=>document.getElementById(id),other=team=>team==='red'?'blue':'red';
const shuffle=list=>{const copy=list.slice();for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy};
const role=id=>characters.find(character=>character.id===Number(id));
const sideText=team=>team==='red'?'紅方':'藍方';
let state=null,timer=null,aiTask=null;

function newState(){
 const deck=shuffle(characters.map(character=>character.id)),battleType=q('battleType').value,playerSide=battleType==='ai'?(Math.random()<.5?'red':'blue'):'both',team=q('teamName').value.trim().slice(0,30)||'我的隊伍',initial=deck.slice(0,8);
 return{deck:deck.slice(8),pool:initial.slice(),appeared:initial.slice(),banned:[],actions:[],picks:{red:[],blue:[]},arrangements:{red:[null,null,null],blue:[null,null,null]},quota:{red:3,blue:3},insertUsed:{red:false,blue:false},reUsed:{red:false,blue:false},roundPrepared:0,step:0,selected:null,placementSelected:null,placementTeam:null,placementQueue:[],seconds:0,battleType,playerSide,names:{red:playerSide==='red'?team:playerSide==='blue'?'電腦酒館隊':'紅方隊伍',blue:playerSide==='blue'?team:playerSide==='red'?'電腦酒館隊':'藍方隊伍'},history:[]};
}
function isHuman(team){return state.battleType==='local'||state.playerSide===team}
function current(){return sequence[state.step]}
function reveal(){if(state.deck.length){const id=state.deck.shift();state.pool.push(id);state.appeared.push(id)}}
function fillPool(){while(state.pool.length<8&&state.deck.length)reveal()}
function take(id,type,team){state.pool=state.pool.filter(value=>value!==id);state.actions.push({id,type,team});if(type==='ban'){state.quota[team]--;state.banned.push({id,team});reveal()}else if(type==='insert'){state.insertUsed[team]=true;state.banned.push({id,team})}else{state.picks[team].push(id);reveal()}}
function record(text){state.history.push(text);q('history').innerHTML=state.history.map(item=>`<li>${item}</li>`).join('')}
function hideAll(){['home','game','placement','result'].forEach(id=>q(id).classList.add('hidden'))}

function start(){state=newState();hideAll();q('game').classList.remove('hidden');q('matchTitle').textContent=`${state.names.red} VS ${state.names.blue}`;q('sideHint').textContent=state.battleType==='ai'?`你被分配為${sideText(state.playerSide)}`:'雙人同機操作';render();beginStep()}
function beginStep(){
 clearInterval(timer);clearTimeout(aiTask);state.selected=null;
 if(state.step>=sequence.length){startPlacement();return}
 const phase=current();
 if(phase.roundStart&&state.roundPrepared<phase.round){fillPool();state.roundPrepared=phase.round;record(`第 ${phase.round} 輪開始，酒館補回 ${state.pool.length} 名角色`)}
 if(phase.type==='ban'&&state.quota[phase.team]<=0){record(`${sideText(phase.team)}禁角額度已用完，自動跳過`);state.step++;render();aiTask=setTimeout(beginStep,350);return}
 if(phase.type==='insert'&&state.insertUsed[phase.team]){state.step++;render();aiTask=setTimeout(beginStep,250);return}
 if(phase.type==='re'&&state.reUsed[phase.team]){state.step++;render();aiTask=setTimeout(beginStep,250);return}
 state.seconds=phase.type==='re'?60:(phase.type==='pick'?30:10);render();
 timer=setInterval(()=>{state.seconds--;renderTimer();if(state.seconds<=0){clearInterval(timer);phase.type==='pick'?timeoutPick():skip(true)}},1000);
 if(!isHuman(phase.team))aiTask=setTimeout(aiMove,650);
}
function render(){
 const phase=current();q('redName').textContent=state.names.red;q('blueName').textContent=state.names.blue;q('redQuota').textContent=state.quota.red;q('blueQuota').textContent=state.quota.blue;q('redSpecial').textContent=`Insert ${state.insertUsed.red?'已用':'可用'}・RE ${state.reUsed.red?'已用':'可用'}`;q('blueSpecial').textContent=`Insert ${state.insertUsed.blue?'已用':'可用'}・RE ${state.reUsed.blue?'已用':'可用'}`;q('poolCount').textContent=`${state.pool.length} / 8`;
 if(phase){const labels={re:`第 ${phase.round} 輪 RE 階段`,ban:'一般 Ban',insert:`是否在${sideText(other(phase.team))}選角前使用 Insert Ban`,pick:`選擇第 ${state.picks[phase.team].length+1} 名角色`};q('turnText').className=`turn-text ${phase.team}-text`;q('turnText').textContent=`${sideText(phase.team)}・${labels[phase.type]}`;q('confirm').textContent=phase.type==='re'?'使用 RE':phase.type==='insert'?'確定 Insert Ban':phase.type==='ban'?'確定 Ban':'確定選角';q('skip').textContent=phase.type==='re'?'本輪不使用 RE':phase.type==='insert'?'不使用 Insert Ban':'跳過，不 Ban 角色';q('skip').classList.toggle('hidden',phase.type==='pick');q('confirm').disabled=!isHuman(phase.team)||(phase.type!=='re'&&!state.selected);q('skip').disabled=!isHuman(phase.team)}
 const selectable=phase&&phase.type!=='re'&&isHuman(phase.team);q('pool').innerHTML=state.pool.map(id=>{const c=role(id),selected=state.selected===id;return`<button class="card ${selected?'selected':''} ${!selectable?'locked':''}" data-id="${id}">${avatarHtml(id)}<div class="name">${c.name}</div></button>`}).join('');
 q('pool').querySelectorAll('.card').forEach(card=>card.onclick=()=>select(Number(card.dataset.id)));
 const activeOrder=Math.max(0,pickOrder.findIndex(([team,index])=>!state.picks[team][index]));
 q('pickOrder').innerHTML=pickOrder.map(([team,index],orderIndex)=>`${orderIndex?'<i>→</i>':''}<span class="${team} ${orderIndex===activeOrder?'active':''} ${state.picks[team][index]?'done':''}">${team==='red'?'紅':'藍'}${index+1}</span>`).join('');
 q('seats').innerHTML=['red','blue'].map(team=>`<section class="picked-team ${team}"><h3>${sideText(team)}已選</h3><div class="team-seats">${[0,1,2].map(index=>seatCard(team,index,state.picks[team][index])).join('')}</div></section>`).join('');renderTimer();
}
function seatCard(team,index,id){const label=`${team==='red'?'紅':'藍'}${index+1}`;if(!id)return`<div class="seat ${team} empty"><div><div class="seat-label">${label}</div>尚未選擇</div></div>`;const c=role(id);return`<div class="seat ${team}"><div class="seat-label">${label}</div>${avatarHtml(id)}<div class="name">${c.name}</div></div>`}
function renderTimer(){q('timer').textContent=state.seconds?`${state.seconds}s`:'';q('timer').classList.toggle('danger',state.seconds>0&&state.seconds<=3)}
function select(id){const phase=current();if(!phase||phase.type==='re'||!isHuman(phase.team))return;state.selected=state.selected===id?null:id;render()}
function advance(){state.step++;render();setTimeout(beginStep,250)}
function useRe(team){state.reUsed[team]=true;state.pool=[];fillPool();record(`${sideText(team)}使用 RE，移除全場並重翻 ${state.pool.length} 名角色`)}
function confirm(){const phase=current();if(!phase||!isHuman(phase.team)||(phase.type!=='re'&&!state.selected))return;clearInterval(timer);if(phase.type==='re'){useRe(phase.team);advance();return}const c=role(state.selected);take(state.selected,phase.type,phase.team);if(phase.type==='insert')record(`${sideText(phase.team)}使用 Insert Ban 禁用「${c.name}」，本輪不補新角色`);else record(`${sideText(phase.team)}${phase.type==='ban'?'Ban':'選擇'}「${c.name}」${phase.type==='ban'?`（剩餘 ${state.quota[phase.team]} 次）`:''}`);advance()}
function skip(timeout=false){const phase=current();if(!phase||phase.type==='pick'||(!isHuman(phase.team)&&!timeout))return;clearInterval(timer);const label=phase.type==='re'?'RE':phase.type==='insert'?'Insert Ban':'一般 Ban';record(`${sideText(phase.team)}${timeout?`${label} 階段逾時`:`本階段不使用 ${label}`}`);advance()}
function timeoutPick(){const phase=current();if(!phase||phase.type!=='pick')return;state.selected=state.pool[Math.floor(Math.random()*state.pool.length)];const c=role(state.selected);take(state.selected,'pick',phase.team);record(`${sideText(phase.team)}選角逾時，自動選擇「${c.name}」`);state.step++;render();setTimeout(beginStep,250)}
function aiMove(){const phase=current();if(!phase||isHuman(phase.team))return;clearInterval(timer);if(phase.type==='re'){if(Math.random()<.35)useRe(phase.team);else record(`${sideText(phase.team)}本輪不使用 RE`);advance();return}if(phase.type==='insert'&&Math.random()>=.45){record(`${sideText(phase.team)}本階段不使用 Insert Ban`);advance();return}const id=state.pool[Math.floor(Math.random()*state.pool.length)],c=role(id);take(id,phase.type,phase.team);if(phase.type==='insert')record(`${sideText(phase.team)}使用 Insert Ban 禁用「${c.name}」，本輪不補新角色`);else record(`${sideText(phase.team)}${phase.type==='ban'?'Ban':'選擇'}「${c.name}」${phase.type==='ban'?`（剩餘 ${state.quota[phase.team]} 次）`:''}`);advance()}

function startPlacement(){
 clearInterval(timer);clearTimeout(aiTask);hideAll();q('placement').classList.remove('hidden');
 if(state.battleType==='ai'){const cpu=other(state.playerSide);state.arrangements[cpu]=shuffle(state.picks[cpu]);state.placementQueue=[state.playerSide]}else state.placementQueue=['red','blue'];
 nextPlacement();
}
function nextPlacement(){
 if(!state.placementQueue.length){showResult();return}
 state.placementTeam=state.placementQueue.shift();state.placementSelected=null;q('placementBoard').classList.add('hidden');q('handoff').classList.remove('hidden');q('handoffTitle').textContent=`請將畫面交給${sideText(state.placementTeam)}・${state.names[state.placementTeam]}`;
}
function openPlacement(){q('handoff').classList.add('hidden');q('placementBoard').classList.remove('hidden');renderPlacement()}
function renderPlacement(){
 const team=state.placementTeam,placed=state.arrangements[team];q('placementTitle').textContent=`${sideText(team)}・${state.names[team]}安排座位`;
 q('placementTray').innerHTML=state.picks[team].map(id=>{const c=role(id),used=placed.includes(id),selected=state.placementSelected===id;return`<button class="card ${selected?'selected':''} ${used?'placed':''}" data-id="${id}">${avatarHtml(id)}<div class="name">${c.name}</div></button>`}).join('');
 q('placementTray').querySelectorAll('.card').forEach(card=>card.onclick=()=>{const id=Number(card.dataset.id);if(placed.includes(id)){state.arrangements[team]=placed.map(value=>value===id?null:value);state.placementSelected=id}else state.placementSelected=state.placementSelected===id?null:id;renderPlacement()});
 q('placementTable').innerHTML=tableHtml(false,team);q('placementTable').querySelectorAll('.table-seat[data-own="true"]').forEach(seat=>seat.onclick=()=>placeAt(Number(seat.dataset.index)));
 q('confirmPlacement').disabled=state.arrangements[team].some(id=>!id);
}
function placeAt(index){const team=state.placementTeam;if(!state.placementSelected)return;const old=state.arrangements[team][index];state.arrangements[team]=state.arrangements[team].map(id=>id===state.placementSelected?null:id);state.arrangements[team][index]=state.placementSelected;state.placementSelected=old||null;renderPlacement()}
function tableHtml(reveal,activeTeam=null){return`<div class="round-table ${reveal?'revealed':''}"><div class="table-ring"></div><div class="table-center"><b>${reveal?'雙方陣容':'秘密排座中'}</b><span>${reveal?'同時公開':sideText(activeTeam)+'配置中'}</span></div>${tableOrder.map(([team,index],position)=>{const id=state.arrangements[team][index],own=team===activeTeam,c=role(id);const visible=reveal||own;return`<button class="table-seat pos-${position} ${team} ${id?'filled':''}" data-team="${team}" data-index="${index}" data-own="${own}">${visible&&c?`${avatarHtml(id,'table-avatar')}<span>${c.name}</span>`:`<strong>${team==='red'?'紅':'藍'}${index+1}</strong><small>${id?'已保密':'尚未安排'}</small>`}</button>`}).join('')}<div class="direction-arrow">➜</div></div>`}
function confirmPlacement(){if(state.arrangements[state.placementTeam].some(id=>!id))return;nextPlacement()}

function showResult(){hideAll();q('result').classList.remove('hidden');q('resultTable').innerHTML=tableHtml(true);renderResultList('red');renderResultList('blue');q('draftMatrix').innerHTML=state.appeared.map((id,index)=>matrixCard(id,index)).join('')}
function renderResultList(team){q(`${team}ResultList`).innerHTML=state.picks[team].map((id,index)=>{const c=role(id);return`<div class="result-pick"><b>${index+1}</b>${avatarHtml(id)}<span>${c.name}</span></div>`}).join('')}
function actionFor(id){return state.actions.find(action=>action.id===id)}
function matrixClass(id){const action=actionFor(id);return action?`${action.team}-${action.type==='insert'?'ban':action.type}`:'neutral'}
function matrixCard(id,index){const c=role(id),action=actionFor(id),label=action?(action.type==='pick'?'選':action.type==='insert'?'插禁':'禁'):'';return`<div class="matrix-card ${matrixClass(id)}"><em>${index+1}</em>${avatarHtml(id)}<span>${c.name}</span>${action?`<small>${sideText(action.team)}${label}</small>`:''}</div>`}

async function saveImage(){
 q('saveImage').disabled=true;q('saveImage').textContent='圖片生成中…';
 try{const url=await makeResultImage();q('resultImage').src=url;q('downloadImage').href=url;q('imageModal').classList.remove('hidden')}catch(error){alert(`圖片生成失敗：${error.message}`)}finally{q('saveImage').disabled=false;q('saveImage').textContent='儲存圖片'}
}
function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error(`無法載入 ${src}`));img.src=src})}
async function makeResultImage(){
 const cols=8,rows=Math.ceil(state.appeared.length/cols),canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1060+rows*150;const ctx=canvas.getContext('2d');
 const sprite=await loadImage(SPRITE_DATA);
 const bg=ctx.createLinearGradient(0,0,0,canvas.height);bg.addColorStop(0,'#17284e');bg.addColorStop(1,'#060b17');ctx.fillStyle=bg;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.textAlign='center';ctx.fillStyle='#ffe29a';ctx.font='900 48px sans-serif';ctx.fillText('星杯酒館・選角結果',800,70);ctx.font='700 25px sans-serif';ctx.fillStyle='#c8d3ef';ctx.fillText(`${state.names.red}  VS  ${state.names.blue}`,800,112);
 drawCanvasTable(ctx,sprite,800,390,650,245);
 const top=690;ctx.fillStyle='#ff96a6';ctx.font='900 28px sans-serif';ctx.fillText('紅方選角',155,top);ctx.fillStyle='#f3c967';ctx.fillText('選角矩陣',800,top);ctx.fillStyle='#83c1ff';ctx.fillText('藍方選角',1445,top);
 drawSideList(ctx,sprite,'red',155,top+75);drawSideList(ctx,sprite,'blue',1445,top+75);
 state.appeared.forEach((id,i)=>{const x=360+(i%cols)*112,y=top+60+Math.floor(i/cols)*150;drawMatrixCanvas(ctx,sprite,id,i+1,x,y)});
 return canvas.toDataURL('image/png');
}
function circleImage(ctx,sprite,id,x,y,r,border){const index=spriteIndex.get(Number(id)),sx=(index%8)*128,sy=Math.floor(index/8)*128;ctx.save();ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.clip();ctx.drawImage(sprite,sx,sy,128,128,x-r,y-r,r*2,r*2);ctx.restore();ctx.strokeStyle=border;ctx.lineWidth=7;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.stroke()}
function drawCanvasTable(ctx,sprite,cx,cy,rx,ry){ctx.strokeStyle='#5d5b50';ctx.lineWidth=24;ctx.beginPath();ctx.ellipse(cx,cy,rx,ry,0,0,Math.PI*2);ctx.stroke();const points=[[-.63,.80],[.63,.80],[.98,.05],[.63,-.80],[-.63,-.80],[-.98,.05]];tableOrder.forEach(([team,index],i)=>{const id=state.arrangements[team][index],x=cx+points[i][0]*rx,y=cy+points[i][1]*ry,c=role(id);circleImage(ctx,sprite,id,x,y,65,team==='red'?'#ff91a2':'#83bfff');ctx.fillStyle='#f6f8ff';ctx.font='800 20px sans-serif';ctx.fillText(c.name,x,y+92)});ctx.fillStyle='#ffe29a';ctx.font='900 34px sans-serif';ctx.fillText('雙方陣容',cx,cy-5);ctx.fillStyle='#aebbd9';ctx.font='700 22px sans-serif';ctx.fillText('同時公開',cx,cy+34)}
function drawSideList(ctx,sprite,team,x,y){state.picks[team].forEach((id,i)=>{const c=role(id),cy=y+i*160;circleImage(ctx,sprite,id,x,cy,52,'#f1c65f');ctx.fillStyle='#f7f8ff';ctx.font='800 20px sans-serif';ctx.fillText(`${i+1}. ${c.name}`,x,cy+80)})}
function drawMatrixCanvas(ctx,sprite,id,number,x,y){const cls=matrixClass(id),styles={neutral:['#293957','#65779d'],'red-ban':['#531a25','#f0647b'],'blue-ban':['#132f58','#67aeff'],'red-pick':['#551b26','#f1c65f'],'blue-pick':['#13345f','#67aeff']},[fill,border]=styles[cls];ctx.fillStyle=fill;ctx.strokeStyle=border;ctx.lineWidth=5;ctx.beginPath();ctx.roundRect(x-48,y-46,96,118,14);ctx.fill();ctx.stroke();circleImage(ctx,sprite,id,x,y-4,34,border);ctx.fillStyle='#fff';ctx.font='800 15px sans-serif';ctx.fillText(role(id).name,x,y+54);ctx.fillStyle='#dbe4fa';ctx.font='700 13px sans-serif';ctx.fillText(String(number),x-34,y-29)}
function home(){clearInterval(timer);clearTimeout(aiTask);hideAll();q('home').classList.remove('hidden')}
q('start').onclick=start;q('confirm').onclick=confirm;q('skip').onclick=()=>skip(false);q('quit').onclick=home;q('placementHome').onclick=home;q('resultHome').onclick=home;q('again').onclick=start;q('readyPlace').onclick=openPlacement;q('confirmPlacement').onclick=confirmPlacement;q('saveImage').onclick=saveImage;q('closeImage').onclick=()=>q('imageModal').classList.add('hidden');q('imageModal').onclick=event=>{if(event.target===q('imageModal'))q('imageModal').classList.add('hidden')};
})();
